def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    if destination_node in unvisited_nodes:
        return destination_node
    min_score = float('inf')
    next_node = None
    for node in unvisited_nodes:
        proximity = distance_matrix[current_node][node]
        distance_node_to_destination = distance_matrix[node][destination_node]
        if distance_node_to_destination == 0:
            ratio = float('inf')
        else:
            ratio = proximity / distance_node_to_destination
        score = proximity + 0.3 * ratio
        if score < min_score:
            min_score = score
            next_node = node
    return next_node

def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    num_unvisited = len(unvisited_nodes)
    def candidate_score(node):
        distance_to_node = distance_matrix[current_node][node]
        distance_to_destination = distance_matrix[node][destination_node]
        weight = (1.0 + 1.0 / (1.0 + distance_to_destination)) * (num_unvisited / (num_unvisited + 1.0))
        return distance_to_node * weight + distance_to_destination * (1 - weight)
    next_node = min(unvisited_nodes, key=lambda node: candidate_score(node))
    return next_node

def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    if not unvisited_nodes:
        return destination_node

    candidates = []
    for node in unvisited_nodes:
        immediate_distance = distance_matrix[current_node][node]
        remaining_unvisited = unvisited_nodes - {node}
        remaining_connections = sum(distance_matrix[node][n] for n in remaining_unvisited)
        total_distance = immediate_distance + (1 / (remaining_connections + 1e-6))
        candidates.append((node, total_distance))

    next_node, _ = min(candidates, key=lambda x: x[1])
    return next_node
